  corpusFileCount: number;
  deterministicSeeds: DeterministicKeywordSeed[];
  hostProposalRefs: string[];
  queries: Array<{
    queryId: string;
    terms: string[];
    sourceRefs: string[];
    hitCount: number;
    truncated: boolean;
  }>;
  candidates: Array<{
    path: string;
    score: number;
    rank: number;
    reasons: string[];
